def transform(grid):
    """Extend each 8-connected foreground component's rightmost point to the right edge in color 1."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] != bg:
                            seen.add((nr, nc))
                            q.append((nr, nc))
            # Extend on the row of the component's rightmost foreground cell.
            mr, mc = max(cells, key=lambda x: (x[1], -x[0]))
            for cc in range(mc + 1, w):
                out[mr][cc] = 1
    return out
